beforeExample:
package test;
import org.eclipse.jdt.core.dom.IBinding;

public class MyClass {
    public void someMethod(IBinding binding) {
        if (binding != null && binding.getKind() == IBinding.PACKAGE) {
            System.out.println("It's a package!");
        }
    }
}

afterExample:
package test;
import org.eclipse.jdt.core.dom.IBinding;

public class MyClass {
    public void someMethod(IBinding binding) {
        if (binding != null && (binding.getKind() == IBinding.PACKAGE || binding.getKind() == IBinding.MODULE)) {
            System.out.println("It's a package!");
        }
    }
}

negativeExample:
package test;
import org.eclipse.jdt.core.dom.IBinding;

public class MyClass {
    public void someMethod(IBinding binding) {
        if (binding != null && binding.getKind() == IBinding.TYPE) { // Should not match
            System.out.println("It's a type!");
        }
    }
}
